# Atualizacao V9 de producao - Relatorio Limites de Destinatarios
[CmdletBinding(SupportsShouldProcess, ConfirmImpact = 'High')]
param(
    [string]$ProductionRoot = '',
    [switch]$SkipJavaScriptValidation
)

$ErrorActionPreference = 'Stop'
$PackageName = 'update-relatorio-limite-destinatarios-v9'
$ModuleName = 'relatorio-limite-destinatarios'
$Payloads = [ordered]@{
    'core\router.ps1' = ''
    'web\js\app.js' = ''
    'modules\relatorio-limite-destinatarios\api.ps1' = ''
    'modules\relatorio-limite-destinatarios\module.json' = 'H4sIAAAAAAAACkXOQQrCQAwF0H1PEWZtV+66VXeC4A1iJ9TANCmZFBTxMB7AlUfoxWRapdvw/v95VABBsKfQQDBK6GqsdeKenepI2VnQ0Vhz2BTr7GnGx5lkiAT7H5teq4uUW+PBWaXonUoekyMoLN0l969fchAxQ4t8wwyicLi1V5SO4CSJhWBQg6j99BbWZaJFp07tXvrP5fXps+6T4CVRDA24jTSf1CJZaGBbPasvLbbPyvgAAAA='
    'modules\relatorio-limite-destinatarios\page.html' = ''
    'modules\relatorio-limite-destinatarios\script.js' = ''
    'modules\relatorio-limite-destinatarios\style.css' = ''
}
$ExpectedHashes = [ordered]@{
    'core\router.ps1' = '7DDB1B74B0BE6434B75D7D8C3C93B68CA2C90B9DB02CF94D60FCD13B2D19E3C6'
    'web\js\app.js' = 'E7B8967F3729936473AC08306C661F126299D899D98678C3058DA9D11F3708DE'
    'modules\relatorio-limite-destinatarios\api.ps1' = 'FE6800E3D320D2030C6E27AC7D25351DC109FA14F13AE0DEED8B15F4914F9CC5'
    'modules\relatorio-limite-destinatarios\module.json' = '6654AB7B15D16627D3EBC4E5222B67E67DAF53734259762BFE972F2A3C126746'
    'modules\relatorio-limite-destinatarios\page.html' = '475DA773A622E01EAFDAE268C3687172E1DA0BCF83AD5103174CE061167A2E90'
    'modules\relatorio-limite-destinatarios\script.js' = '359A31984BA194021C59189809CDD9B573F8CFB7BB508CA3F2DFF6114CDCC74B'
    'modules\relatorio-limite-destinatarios\style.css' = '88EE393722E8E230C87247DECAA608E5616E4C68E97033FDCF2905E8E997D65E'
}

function Find-ProductionRoot([string]$RequestedPath) {
    $Candidates = @($RequestedPath, $PSScriptRoot, (Get-Location).Path, 'C:\Temp\SantanderSupportWebV2_PROD')
    foreach ($Candidate in $Candidates) {
        if ($Candidate -and (Test-Path -LiteralPath (Join-Path $Candidate 'config.json') -PathType Leaf)) {
            return (Resolve-Path -LiteralPath $Candidate).Path.TrimEnd('\')
        }
    }
    $Entered = (Read-Host 'Indique o caminho completo da pasta SantanderSupportWebV2 de producao').Trim('"').Trim()
    if (-not (Test-Path -LiteralPath (Join-Path $Entered 'config.json') -PathType Leaf)) { throw 'Pasta de producao invalida.' }
    (Resolve-Path -LiteralPath $Entered).Path.TrimEnd('\')
}

function Expand-Payload([string]$Base64, [string]$Destination) {
    $InputStream = [IO.MemoryStream]::new([Convert]::FromBase64String($Base64))
    $Gzip = [IO.Compression.GZipStream]::new($InputStream, [IO.Compression.CompressionMode]::Decompress)
    $Output = [IO.MemoryStream]::new()
    try { $Gzip.CopyTo($Output); [IO.File]::WriteAllBytes($Destination, $Output.ToArray()) }
    finally { $Output.Dispose(); $Gzip.Dispose(); $InputStream.Dispose() }
}

function Test-PublishedFiles([string]$Root) {
    foreach ($Relative in $ExpectedHashes.Keys) {
        $Path = Join-Path $Root $Relative
        if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { throw "Ficheiro publicado em falta: $Relative" }
        if ((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash -ne $ExpectedHashes[$Relative]) { throw "Hash final invalido: $Relative" }
    }
    $Tokens = $null; $Errors = $null
    [Management.Automation.Language.Parser]::ParseFile((Join-Path $Root 'modules\relatorio-limite-destinatarios\api.ps1'), [ref]$Tokens, [ref]$Errors) | Out-Null
    if ($Errors.Count) { throw "PowerShell invalido no modulo: $($Errors[0].Message)" }
    Get-Content -LiteralPath (Join-Path $Root 'modules\relatorio-limite-destinatarios\module.json') -Raw -Encoding UTF8 | ConvertFrom-Json | Out-Null
    if (-not $SkipJavaScriptValidation) {
        $Node = Get-Command node -ErrorAction SilentlyContinue
        if ($Node) {
            & $Node.Source --check (Join-Path $Root 'modules\relatorio-limite-destinatarios\script.js')
            if ($LASTEXITCODE -ne 0) { throw 'JavaScript invalido no modulo.' }
        }
    }
}

$ProductionRoot = Find-ProductionRoot $ProductionRoot
$Config = Get-Content -LiteralPath (Join-Path $ProductionRoot 'config.json') -Raw -Encoding UTF8 | ConvertFrom-Json
if ([string]$Config.environment -ne 'production') { throw "Destino recusado: environment=$($Config.environment); esperado production." }

$Stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$BackupRoot = Join-Path $ProductionRoot "backups\$PackageName-$Stamp"
$StageRoot = Join-Path $BackupRoot 'stage'
$ReportPath = Join-Path $BackupRoot 'install-report.json'
$Published = [Collections.Generic.List[string]]::new()

Write-Host "Producao: $ProductionRoot" -ForegroundColor Cyan
Write-Host "Modulo: $ModuleName" -ForegroundColor Cyan
Write-Host 'O servidor deve ser reiniciado depois da instalacao.' -ForegroundColor Yellow
if (-not $PSCmdlet.ShouldProcess($ProductionRoot, 'Instalar relatorio de limites de destinatarios')) { return }

try {
    New-Item -ItemType Directory -Path $StageRoot -Force | Out-Null
    foreach ($Relative in $Payloads.Keys) {
        $StageFile = Join-Path $StageRoot $Relative
        New-Item -ItemType Directory -Path (Split-Path $StageFile) -Force | Out-Null
        Expand-Payload $Payloads[$Relative] $StageFile
        if ((Get-FileHash -LiteralPath $StageFile -Algorithm SHA256).Hash -ne $ExpectedHashes[$Relative]) { throw "Payload corrompido: $Relative" }
    }
    Test-PublishedFiles $StageRoot

    foreach ($Relative in $Payloads.Keys) {
        $Target = Join-Path $ProductionRoot $Relative
        $Backup = Join-Path $BackupRoot "original\$Relative"
        if (Test-Path -LiteralPath $Target -PathType Leaf) {
            New-Item -ItemType Directory -Path (Split-Path $Backup) -Force | Out-Null
            Copy-Item -LiteralPath $Target -Destination $Backup -Force
        }
        New-Item -ItemType Directory -Path (Split-Path $Target) -Force | Out-Null
        Copy-Item -LiteralPath (Join-Path $StageRoot $Relative) -Destination $Target -Force
        $Published.Add($Relative)
    }
    Test-PublishedFiles $ProductionRoot

    [ordered]@{ success=$true; package=$PackageName; completedAt=(Get-Date).ToString('o'); productionRoot=$ProductionRoot; backupRoot=$BackupRoot; files=@($Payloads.Keys); restartRequired=$true } |
        ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $ReportPath -Encoding UTF8
    Write-Host 'ATUALIZACAO CONCLUIDA COM SUCESSO.' -ForegroundColor Green
    Write-Host "Backup e relatorio: $BackupRoot" -ForegroundColor Cyan
}
catch {
    $Failure = $_.Exception.Message
    Write-Warning "Falha: $Failure. A restaurar os originais."
    foreach ($Relative in $Published) {
        $Target = Join-Path $ProductionRoot $Relative
        $Backup = Join-Path $BackupRoot "original\$Relative"
        if (Test-Path -LiteralPath $Backup -PathType Leaf) { Copy-Item -LiteralPath $Backup -Destination $Target -Force }
        elseif (Test-Path -LiteralPath $Target -PathType Leaf) { Remove-Item -LiteralPath $Target -Force }
    }
    if (Test-Path -LiteralPath $BackupRoot -PathType Container) {
        [ordered]@{ success=$false; package=$PackageName; failedAt=(Get-Date).ToString('o'); error=$Failure; rollbackAttempted=$true } |
            ConvertTo-Json | Set-Content -LiteralPath $ReportPath -Encoding UTF8
    }
    throw
}